// Mapa de NodeIds del README del PLC Sim Server.
const tags = [{"path":"Motor1.Status","nodeId":"ns=2;s=Motor1.Status","dt":"String"},{"path":"Motor1.RPM","nodeId":"ns=2;s=Motor1.RPM","dt":"Double"},{"path":"Motor1.Corriente_A","nodeId":"ns=2;s=Motor1.Corriente_A","dt":"Double"},{"path":"Motor1.Falla","nodeId":"ns=2;s=Motor1.Falla","dt":"Boolean"},{"path":"Motor1.Comando_Run","nodeId":"ns=2;s=Motor1.Comando_Run","dt":"Boolean"},{"path":"Motor2.Status","nodeId":"ns=2;s=Motor2.Status","dt":"String"},{"path":"Motor2.RPM","nodeId":"ns=2;s=Motor2.RPM","dt":"Double"},{"path":"Motor2.Corriente_A","nodeId":"ns=2;s=Motor2.Corriente_A","dt":"Double"},{"path":"Motor2.Falla","nodeId":"ns=2;s=Motor2.Falla","dt":"Boolean"},{"path":"Motor2.Comando_Run","nodeId":"ns=2;s=Motor2.Comando_Run","dt":"Boolean"},{"path":"LazoTemp.PV_Temp_C","nodeId":"ns=2;s=LazoTemp.PV_Temp_C","dt":"Double"},{"path":"LazoTemp.Modo","nodeId":"ns=2;s=LazoTemp.Modo","dt":"String"},{"path":"LazoTemp.SP_Temp_C","nodeId":"ns=2;s=LazoTemp.SP_Temp_C","dt":"Double"},{"path":"LazoTemp.Salida_Valvula_Pct","nodeId":"ns=2;s=LazoTemp.Salida_Valvula_Pct","dt":"Double"},{"path":"LazoTemp.Modo_Cmd","nodeId":"ns=2;s=LazoTemp.Modo_Cmd","dt":"String"},{"path":"MT1.Posicion","nodeId":"ns=2;s=MT1.Posicion","dt":"String"},{"path":"MT1.kV","nodeId":"ns=2;s=MT1.kV","dt":"Double"},{"path":"MT1.A","nodeId":"ns=2;s=MT1.A","dt":"Double"},{"path":"MT1.MW","nodeId":"ns=2;s=MT1.MW","dt":"Double"},{"path":"MT1.Comando_Open_Close","nodeId":"ns=2;s=MT1.Comando_Open_Close","dt":"Boolean"},{"path":"MT2.Posicion","nodeId":"ns=2;s=MT2.Posicion","dt":"String"},{"path":"MT2.kV","nodeId":"ns=2;s=MT2.kV","dt":"Double"},{"path":"MT2.A","nodeId":"ns=2;s=MT2.A","dt":"Double"},{"path":"MT2.MW","nodeId":"ns=2;s=MT2.MW","dt":"Double"},{"path":"MT2.Comando_Open_Close","nodeId":"ns=2;s=MT2.Comando_Open_Close","dt":"Boolean"},{"path":"InversorSolar.DC_V","nodeId":"ns=2;s=InversorSolar.DC_V","dt":"Double"},{"path":"InversorSolar.DC_A","nodeId":"ns=2;s=InversorSolar.DC_A","dt":"Double"},{"path":"InversorSolar.AC_Power_kW","nodeId":"ns=2;s=InversorSolar.AC_Power_kW","dt":"Double"},{"path":"InversorSolar.Eficiencia_Pct","nodeId":"ns=2;s=InversorSolar.Eficiencia_Pct","dt":"Double"},{"path":"InversorSolar.Falla","nodeId":"ns=2;s=InversorSolar.Falla","dt":"Boolean"},{"path":"InversorSolar.Curtailment_Setpoint_Pct","nodeId":"ns=2;s=InversorSolar.Curtailment_Setpoint_Pct","dt":"Double"}];
flow.set('tagList', tags);
for (const t of tags) {
    node.send({ topic: t.nodeId, datatype: t.dt, path: t.path, interval: 250 });
}
node.status({ fill: 'blue', shape: 'dot', text: tags.length + ' tags' });
return null;

// Guarda el último valor de cada tag y lo reparte a los widgets.
const path = msg.topic.replace('ns=2;s=', '').split(';')[0];
const tags = flow.get('tags') || {};
tags[path] = { value: msg.payload, ts: msg.sourceTimestamp, rx: Date.now() };
flow.set('tags', tags);
flow.set('lastRx', Date.now());

const out = new Array(31).fill(null);
const payload = msg.payload;
switch (path) {
    case 'Motor1.RPM':
        out[0] = { topic: 'Motor1.RPM', payload };
        break;
    case 'Motor1.Status':
        out[1] = { topic: 'Motor1.Status', payload };
        break;
    case 'Motor1.Corriente_A':
        out[2] = (() => { const msg = { topic: 'Motor1.Corriente_A', payload }; msg.payload = Number(msg.payload).toFixed(1); return msg; })();
        break;
    case 'Motor1.Falla':
        out[3] = (() => { const msg = { topic: 'Motor1.Falla', payload }; msg.payload = msg.payload ? '⚠ FALLA' : 'OK'; return msg; })();
        break;
    case 'Motor1.Comando_Run':
        out[4] = { topic: 'Motor1.Comando_Run', payload };
        break;
    case 'Motor2.RPM':
        out[5] = { topic: 'Motor2.RPM', payload };
        break;
    case 'Motor2.Status':
        out[6] = { topic: 'Motor2.Status', payload };
        break;
    case 'Motor2.Corriente_A':
        out[7] = (() => { const msg = { topic: 'Motor2.Corriente_A', payload }; msg.payload = Number(msg.payload).toFixed(1); return msg; })();
        break;
    case 'Motor2.Falla':
        out[8] = (() => { const msg = { topic: 'Motor2.Falla', payload }; msg.payload = msg.payload ? '⚠ FALLA' : 'OK'; return msg; })();
        break;
    case 'Motor2.Comando_Run':
        out[9] = { topic: 'Motor2.Comando_Run', payload };
        break;
    case 'LazoTemp.PV_Temp_C':
        out[10] = { topic: 'LazoTemp.PV_Temp_C', payload };
        break;
    case 'LazoTemp.Modo':
        out[11] = { topic: 'LazoTemp.Modo', payload };
        break;
    case 'LazoTemp.SP_Temp_C':
        out[12] = { topic: 'LazoTemp.SP_Temp_C', payload };
        break;
    case 'LazoTemp.Salida_Valvula_Pct':
        out[13] = (() => { const msg = { topic: 'LazoTemp.Salida_Valvula_Pct', payload }; msg.payload = Math.round(msg.payload); return msg; })();
        break;
    case 'LazoTemp.Modo_Cmd':
        out[14] = { topic: 'LazoTemp.Modo_Cmd', payload };
        break;
    case 'MT1.Posicion':
        out[15] = (() => { const msg = { topic: 'MT1.Posicion', payload }; msg.payload = msg.payload === 'Closed' ? '● CERRADO' : '○ ABIERTO'; return msg; })();
        break;
    case 'MT1.kV':
        out[16] = (() => { const msg = { topic: 'MT1.kV', payload }; msg.payload = Number(msg.payload).toFixed(2); return msg; })();
        break;
    case 'MT1.A':
        out[17] = (() => { const msg = { topic: 'MT1.A', payload }; msg.payload = Number(msg.payload).toFixed(1); return msg; })();
        break;
    case 'MT1.MW':
        out[18] = (() => { const msg = { topic: 'MT1.MW', payload }; msg.payload = Number(msg.payload).toFixed(3); return msg; })();
        break;
    case 'MT1.Comando_Open_Close':
        out[19] = (() => { const msg = { topic: 'MT1.Comando_Open_Close', payload }; msg.payload = msg.payload ? 'cerrar (true)' : 'abrir (false)'; return msg; })();
        break;
    case 'MT2.Posicion':
        out[20] = (() => { const msg = { topic: 'MT2.Posicion', payload }; msg.payload = msg.payload === 'Closed' ? '● CERRADO' : '○ ABIERTO'; return msg; })();
        break;
    case 'MT2.kV':
        out[21] = (() => { const msg = { topic: 'MT2.kV', payload }; msg.payload = Number(msg.payload).toFixed(2); return msg; })();
        break;
    case 'MT2.A':
        out[22] = (() => { const msg = { topic: 'MT2.A', payload }; msg.payload = Number(msg.payload).toFixed(1); return msg; })();
        break;
    case 'MT2.MW':
        out[23] = (() => { const msg = { topic: 'MT2.MW', payload }; msg.payload = Number(msg.payload).toFixed(3); return msg; })();
        break;
    case 'MT2.Comando_Open_Close':
        out[24] = (() => { const msg = { topic: 'MT2.Comando_Open_Close', payload }; msg.payload = msg.payload ? 'cerrar (true)' : 'abrir (false)'; return msg; })();
        break;
    case 'InversorSolar.AC_Power_kW':
        out[25] = (() => { const msg = { topic: 'InversorSolar.AC_Power_kW', payload }; msg.payload = Math.round(msg.payload * 10) / 10; return msg; })();
        break;
    case 'InversorSolar.DC_V':
        out[26] = (() => { const msg = { topic: 'InversorSolar.DC_V', payload }; msg.payload = Number(msg.payload).toFixed(0); return msg; })();
        break;
    case 'InversorSolar.DC_A':
        out[27] = (() => { const msg = { topic: 'InversorSolar.DC_A', payload }; msg.payload = Number(msg.payload).toFixed(1); return msg; })();
        break;
    case 'InversorSolar.Eficiencia_Pct':
        out[28] = (() => { const msg = { topic: 'InversorSolar.Eficiencia_Pct', payload }; msg.payload = Number(msg.payload).toFixed(1); return msg; })();
        break;
    case 'InversorSolar.Falla':
        out[29] = (() => { const msg = { topic: 'InversorSolar.Falla', payload }; msg.payload = msg.payload ? '⚠ FALLA' : 'OK'; return msg; })();
        break;
    case 'InversorSolar.Curtailment_Setpoint_Pct':
        out[30] = (() => { const msg = { topic: 'InversorSolar.Curtailment_Setpoint_Pct', payload }; msg.payload = Math.round(msg.payload); return msg; })();
        break;
}
return out;

// 2ª salida del cliente OPC UA: { error, endpoint, status }
flow.set('connStatus', msg.status || '');
if (msg.error) { flow.set('connError', String(msg.error)); }
return null;

// Stale: sin ninguna notificación de la suscripción en 5 s (kV y RPM tienen ruido, así que
// con el servidor en línea siempre llega algo).
const last = flow.get('lastRx') || 0;
const age = last ? (Date.now() - last) / 1000 : null;
const status = flow.get('connStatus') || '—';
const stale = age === null || age > 5;
node.status({ fill: stale ? 'red' : 'green', shape: 'dot', text: stale ? 'STALE' : 'OK' });
return [
    { payload: stale ? '🔴 DATOS STALE (sin actualizaciones)' : '🟢 EN LÍNEA' },
    { payload: status },
    { payload: age === null ? 'nunca' : age.toFixed(1) + ' s' },
    { payload: flow.get('connError') || '—' }
];

const tags = flow.get('tags') || {};
const v = (p) => tags[p] ? Number(tags[p].value) : null;
const out1 = [], out2 = [];
if (v('LazoTemp.PV_Temp_C') !== null) out1.push({ topic: 'PV °C', payload: v('LazoTemp.PV_Temp_C') });
if (v('LazoTemp.SP_Temp_C') !== null) out1.push({ topic: 'SP °C', payload: v('LazoTemp.SP_Temp_C') });
if (v('InversorSolar.AC_Power_kW') !== null) out2.push({ topic: 'AC kW', payload: v('InversorSolar.AC_Power_kW') });
if (v('InversorSolar.Curtailment_Setpoint_Pct') !== null) out2.push({ topic: 'Curtailment %', payload: v('InversorSolar.Curtailment_Setpoint_Pct') });
// Sin datos frescos (servidor caído) no se agregan puntos: el hueco en el gráfico lo muestra.
const last = flow.get('lastRx') || 0;
if (Date.now() - last > 5000) return null;
return [out1, out2];

const list = flow.get('tagList') || [];
const tags = flow.get('tags') || {};
const now = Date.now();
const fmt = (v) => typeof v === 'number' ? (Number.isInteger(v) ? String(v) : v.toFixed(2)) : String(v);
msg.payload = list.map(t => {
    const s = tags[t.path];
    return {
        nodeId: t.nodeId, dt: t.dt,
        value: s ? fmt(s.value) : '—',
        ts: s && s.ts ? new Date(s.ts).toLocaleTimeString() : '—',
        age: s ? (now - s.rx) / 1000 : null
    };
});
return msg;

// msg.payload = StatusCode de la escritura (o un Error si no hay sesión).
const sc = msg.payload || {};
const name = sc.name || (sc.message ? 'Error: ' + sc.message : String(sc));
const tag = String(msg.topic).replace('ns=2;s=', '').split(';')[0];
const ok = name === 'Good';
node.status({ fill: ok ? 'green' : 'red', shape: 'dot', text: tag + ' → ' + name });
return {
    payload: (ok ? '✔ ' : '✖ ') + tag + ': ' + name + (ok ? '' : (sc.description ? ' — ' + sc.description : '')),
    ui_update: { color: ok ? '#2e7d32' : '#c62828' }
};
